//
// The request state of a route, kept per consumer key. Every request carries the id
// it was dispatched under; an answer to any other id is a stale one -- a newer
// request for the same key was made since -- and is discarded, so a slow answer can
// never overwrite a newer one. Keys never share a request: one key's request never
// touches another's. A released key's request state is removed.
//
// A failed request settles by one rule, the same on every client target: the answer
// shown stays shown while a newer request is awaited; a failed request for the
// arguments that answer was loaded for (a refresh, a poll tick, a retry) keeps it beside
// the failure, and a failed request for other arguments drops it.
//
// Every value held here is plain data (the route's arguments and answer, and a
// decoded problem), so the state stays serializable.

import type { ProblemDetails } from '@portalder/system-api-common';

/** Where one key's request stands. */
